# Library of Congress API
import requests

LOC_API_KEY = "3989a5f99e41487aaef698680537c3f5"
BASE_URL = "https://www.loc.gov/"

def search_loc(query, format=None):
    """Search the Library of Congress"""
    params = {
        "q": query,
        "fo": "json",
        "api_key": LOC_API_KEY
    }
    if format:
        params["fa"] = f"format:<built-in function format>"

    response = requests.get(f"{BASE_URL}/search/", params=params)
    return response.json()

def get_historic_newspapers(date, state=None):
    """Search historic newspapers by date"""
    params = {
        "date": date,
        "fo": "json",
        "api_key": LOC_API_KEY
    }
    if state:
        params["state"] = state

    response = requests.get(f"{BASE_URL}/newspapers/", params=params)
    return response.json()

def get_american_memory_collection(collection):
    """Access American Memory historical collections"""
    response = requests.get(
        f"{BASE_URL}/collections/{collection}",
        params={"fo": "json", "api_key": LOC_API_KEY}
    )
    return response.json()
